effect.shader:
void main() {
    if (strength <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(echoes), 2, 16);
    vec2 p = acScreenNorm - center;

    vec4 soma = vec4(0.0);
    float pesoTot = 0.0;
    float w = 1.0;
    for (int i = 0; i <= 16; i++) {
        if (i >= n) break;
        float t = float(i) / float(n);
        vec2 u = center + p * (1.0 - strength * t);
        soma += texture(inputImg, u) * w;
        pesoTot += w;
        w *= fade;
    }
    fragColor = soma / max(pesoTot, 1e-4);
}
